void Solver::bump_var(int var, double coeff) {
    // Increase the activity of the variable by a scaled increment.
    double inc = var_inc * coeff;
    activity[var] += inc;

    // If any activity grows beyond a safe threshold, rescale all activities
    // and the increment factor to avoid floating‑point overflow.
    const double RESCALE_LIMIT = 1e150;
    if (activity[var] > RESCALE_LIMIT) {
        const double SCALE_FACTOR = 1e-150;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= SCALE_FACTOR;
        }
        var_inc *= SCALE_FACTOR;
    }

    // Keep the VSIDS priority queue up‑to‑date.
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
